      intro: 'ଏହି ଆବେଦନ ସେହି ପ୍ରାଧିକରଣଙ୍କ ପାଖରେ ଦାଖଲ କରାଯାଏ ଯାହାର ଆପଣଙ୍କ ରାଜ୍ୟର ଭଡ଼ା ନିୟନ୍ତ୍ରଣ ଅଧିନିୟମ ଅଧୀନରେ ପରିସର ଉପରେ ଅଧିକାରକ୍ଷେତ୍ର ଅଛି — ସଠିକ୍ ପ୍ରାଧିକରଣ (ରେଣ୍ଟ କଣ୍ଟ୍ରୋଲର, ରେଣ୍ଟ ଟ୍ରିବ୍ୟୁନାଲ, ରେଣ୍ଟ କଣ୍ଟ୍ରୋଲ କୋର୍ଟ, ନିର୍ଦ୍ଦିଷ୍ଟ ପ୍ରାଧିକରଣ, କିମ୍ବା ଏକ ସାଧାରଣ ଦେୱାନୀ ଅଦାଲତ, ରାଜ୍ୟ ଅନୁସାରେ) ଏହି ଡ୍ରାଫ୍ଟର ନିଜ କଜ ଟାଇଟଲରେ ଦେଖାଯାଇଛି।',
